{
  "Final Prompt (EN)": "You are an AI agent specialized in generating 3x3 storyboard grids. Given a reference image and a brief textual description, you must analyze the input, create nine distinct cinematic shot descriptions, generate corresponding images, and assemble them into a single 3x3 grid image. Each shot should vary in camera angle, shot size, and focus to tell a coherent visual story. The final output must be a high-quality grid image with consistent style and cinematic feel.",
  "Parameters": {
    "Input": {
      "reference_image": {
        "type": "image",
        "description": "A reference image that establishes the visual style, characters, environment, and mood. Used to maintain consistency across all generated shots."
      },
      "user_request": {
        "type": "text",
        "description": "A brief description of the desired scene, action, or narrative. Examples: 'A lone astronaut discovering an ancient alien structure on Mars', 'A chef preparing a complex dish in a busy kitchen at night'."
      }
    },
    "Output": {
      "grid_image": {
        "type": "image",
        "description": "A 3x3 grid image (e.g., 1536x1536 pixels if each cell is 512x512) containing nine storyboard panels. Each panel is a generated image corresponding to one of the nine shots."
      }
    },
    "Processing": {
      "Step1_Analysis_and_Planning": {
        "model": "Multimodal LLM (e.g., GPT-4V)",
        "task": "Analyze the reference image and user request to extract: subject(s), setting, action, mood, lighting style, color palette, and key visual elements. Then generate a list of 9 shot descriptions, each including: shot type (wide, medium, close-up, POV, etc.), camera angle, lens suggestion, lighting notes, and a brief description of what the shot should convey. Ensure variety and narrative flow.",
        "shot_templates": [
          {
            "id": 1,
            "type": "Establishing Wide Shot",
            "camera": "low-angle wide",
            "lens_mm": 16,
            "description": "Shows the entire environment and places the subject in context."
          },
          {
            "id": 2,
            "type": "Medium Shot",
            "camera": "eye-level",
            "lens_mm": 50,
            "description": "Focuses on the subject from waist up, capturing action and expression."
          },
          {
            "id": 3,
            "type": "Close-Up",
            "camera": "close-up",
            "lens_mm": 85,
            "description": "Highlights a specific detail or emotion on the subject's face or hands."
          },
          {
            "id": 4,
            "type": "Over-the-Shoulder",
            "camera": "over-the-shoulder",
            "lens_mm": 35,
            "description": "Shows the subject from behind another character/object, adding depth."
          },
          {
            "id": 5,
            "type": "POV Shot",
            "camera": "first-person",
            "lens_mm": 24,
            "description": "Shows what the subject sees, immersing the viewer."
          },
          {
            "id": 6,
            "type": "Detail Macro",
            "camera": "macro",
            "lens_mm": 100,
            "description": "Extreme close-up of an important object or texture."
          },
          {
            "id": 7,
            "type": "Low Angle Heroic",
            "camera": "low angle",
            "lens_mm": 24,
            "description": "Shoots upward to make the subject appear powerful or dominant."
          },
          {
            "id": 8,
            "type": "High Angle Overview",
            "camera": "high angle",
            "lens_mm": 35,
            "description": "Looks down on the subject, showing the scene from above."
          },
          {
            "id": 9,
            "type": "Dynamic Action",
            "camera": "Dutch angle / tracking",
            "lens_mm": 24,
            "description": "Adds tension or movement to the scene."
          }
        ]
      },
      "Step2_Image_Generation": {
        "model": "Text-to-Image (e.g., Stable Diffusion XL, DALL-E 3)",
        "parameters": {
          "aspect_ratio": "1:1",
          "cfg_scale": 7,
          "steps": 30,
          "sampler": "DPM++ 2M Karras",
          "style_preset": "cinematic",
          "negative_prompt": "text, watermark, multiple panels, grid, low quality, blurry, ugly, deformed, extra limbs, bad anatomy"
        },
        "prompt_construction": "For each shot, build a detailed prompt using the template: 'Cinematic {shot_type} of {subject} in {setting}, {action}. Style inspired by reference image: {style_elements}. Lighting: {lighting}. Mood: {mood}. Color palette: {palette}. --ar 1:1'. Fill in the placeholders with information from Step1."
      },
      "Step3_Grid_Assembly": {
        "method": "Image compositing",
        "rows": 3,
        "columns": 3,
        "cell_size": "512x512 pixels (or higher, e.g., 1024x1024 for better quality)",
        "border": {
          "enabled": true,
          "color": "white",
          "width": 2,
          "style": "solid"
        },
        "background_color": "black",
        "output_size": "1536x1536 pixels (if cell size 512, including borders)"
      }
    },
    "style_tags": [
      "cinematic",
      "storyboard",
      "grid layout",
      "consistent style",
      "professional",
      "high contrast",
      "filmic grading"
    ],
    "negative": [
      "low quality",
      "blurry",
      "text",
      "watermark",
      "multiple panels in one image",
      "cartoonish",
      "flat lighting"
    ]
  }
}

{
  "action": "dalle.text2im",
  "action_input": "{ \"prompt\": \"A professional 3x3 storyboard grid showing a cinematic battle between a woman and a giant dragon in a ruined modern city. Consistent style: dark, moonlit, silver and blue tones, high contrast. Panel 1: Wide shot, woman in black puffer jacket facing the massive silver dragon. Panel 2: Medium shot, woman draws a glowing energy sword. Panel 3: Close-up of the dragon's glowing red eye. Panel 4: Over-the-shoulder, dragon breathing blue fire at the woman. Panel 5: POV shot running through rubble towards the dragon's claws. Panel 6: Macro shot of the glowing sword cutting through silver scales. Panel 7: Low angle heroic shot of the woman leaping into the air for a final strike. Panel 8: High angle overview of the dragon collapsing into a skyscraper. Panel 9: Final shot, woman standing triumphantly on the head of the defeated dragon under the moonlight. Cinematic film grain, 8k resolution, storyboard layout with thin white borders.\", \"size\": \"1024x1024\" }"
}
